/** Small, fast, seedable PRNG (mulberry32) with a few helpers. */
export class Rng {
  private s: number

  constructor(seed: number) {
    this.s = seed >>> 0 || 0x9e3779b9
  }

  next(): number {
    let t = (this.s = (this.s + 0x6d2b79f5) >>> 0)
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }

  range(a: number, b: number): number {
    return a + (b - a) * this.next()
  }

  int(a: number, b: number): number {
    return Math.floor(this.range(a, b + 1))
  }

  /** Standard normal via Box–Muller. */
  normal(): number {
    const u = Math.max(1e-9, this.next())
    const v = this.next()
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v)
  }

  pick<T>(list: readonly T[]): T {
    return list[Math.floor(this.next() * list.length)]
  }
}

// Robustness sweep: `node scripts/sweep.ts preset seconds seeds k=v...` → survival + wave stats
import { World, DT, TUNING } from '../src/sim/world.ts'
import { PRESETS, type Params } from '../src/sim/params.ts'
const [id = 'balanced', secArg = '2000', seedArg = '8', ...overrides] = process.argv.slice(2)
const extra: Partial<Params> = {}
for (const o of overrides) {
  const [k, v] = o.split('=')
  if (k in TUNING) (TUNING as Record<string, number>)[k] = Number(v)
  else (extra as Record<string, number>)[k] = Number(v)
}
const preset = PRESETS.find((p) => p.id === id)!
let survived = 0
const lines: string[] = []
for (let s = 0; s < Number(seedArg); s++) {
  const w = new World({ ...preset.params, ...extra, seed: preset.params.seed + s * 101 })
  const B: number[] = []
  const R: number[] = []
  const steps = Math.round(Number(secArg) / DT)
  let gone = ''
  for (let i = 1; i <= steps; i++) {
    w.step()
    if (i % 20 === 0) {
      B.push(w.counts[0])
      R.push(w.counts[1])
    }
    if (!gone && (w.counts[0] === 0 || w.counts[1] === 0)) gone = `${w.counts[0] === 0 ? 'B' : 'R'}@${w.t.toFixed(0)}`
  }
  if (!gone) survived++
  const stat = (a: number[]) => {
    const m = a.reduce((x, y) => x + y, 0) / a.length
    const sd = Math.sqrt(a.reduce((x, y) => x + (y - m) ** 2, 0) / a.length)
    return `${m.toFixed(0)}±${sd.toFixed(0)} [${Math.min(...a)}–${Math.max(...a)}]`
  }
  lines.push(`  s${s}: ${gone || 'ok'.padEnd(6)} B ${stat(B)}  R ${stat(R)}`)
}
console.log(`${id} ${overrides.join(' ')} → survived ${survived}/${seedArg}`)
console.log(lines.join('\n'))

// Headless runs of the garden for tuning presets: `pnpm tune [presetId] [seconds] [seeds]`
import { World, DT, TUNING } from '../src/sim/world.ts'
import { PRESETS, type Params } from '../src/sim/params.ts'

const [presetArg = 'all', secArg = '1200', seedArg = '3', ...overrides] = process.argv.slice(2)
const seconds = Number(secArg)
const seeds = Number(seedArg)
const extra: Partial<Params> = {}
for (const o of overrides) {
  const [k, v] = o.split('=')
  if (k in TUNING) (TUNING as Record<string, number>)[k] = Number(v)
  else (extra as Record<string, number>)[k] = Number(v)
}

for (const preset of PRESETS) {
  if (presetArg !== 'all' && preset.id !== presetArg) continue
  console.log(`\n=== ${preset.name} ${JSON.stringify(extra)}`)
  for (let s = 0; s < seeds; s++) {
    const w = new World({ ...preset.params, ...extra, seed: preset.params.seed + s * 101 })
    const t0 = performance.now()
    const row: string[] = []
    let blueGone = -1
    let redGone = -1
    let maxB = 0
    let maxR = 0
    const steps = Math.round(seconds / DT)
    for (let i = 1; i <= steps; i++) {
      w.step()
      const [b, r] = w.counts
      maxB = Math.max(maxB, b)
      maxR = Math.max(maxR, r)
      if (b === 0 && blueGone < 0) blueGone = w.t
      if (r === 0 && redGone < 0) redGone = w.t
      if (i % Math.round(25 / DT) === 0) row.push(`${b}/${r}/${w.ripe}`)
    }
    const ms = performance.now() - t0
    console.log(
      `seed ${s}: maxB ${maxB} maxR ${maxR} blueGone ${blueGone.toFixed(0)} redGone ${redGone.toFixed(0)} births ${w.totals.births} boops ${w.totals.contacts} (${(ms / 1000).toFixed(1)}s)`,
    )
    if (process.env.ROWS) console.log('  ' + row.join(' '))
  }
}

// Detailed trace of one run: `node scripts/probe.ts preset seconds every k=v...`
import { World, DT, BLUE, RED, TUNING } from '../src/sim/world.ts'
import { PRESETS, type Params } from '../src/sim/params.ts'
const [id = 'balanced', secArg = '300', everyArg = '10', ...overrides] = process.argv.slice(2)
const extra: Partial<Params> = {}
for (const o of overrides) {
  const [k, v] = o.split('=')
  if (k in TUNING) (TUNING as Record<string, number>)[k] = Number(v)
  else (extra as Record<string, number>)[k] = Number(v)
}
const preset = PRESETS.find((p) => p.id === id)!
const w = new World({ ...preset.params, ...extra })
const every = Math.round(Number(everyArg) / DT)
let lastT = w.totals
let prev = JSON.parse(JSON.stringify(w.totals))
for (let i = 1; i <= Math.round(Number(secArg) / DT); i++) {
  w.step()
  if (i % every === 0) {
    const acts: Record<string, number> = {}
    let eb = 0, er = 0
    for (const b of w.blobs) if (b.alive) { acts[(b.kind === BLUE ? 'b.' : 'r.') + b.action] = (acts[(b.kind === BLUE ? 'b.' : 'r.') + b.action] ?? 0) + 1; if (b.kind === BLUE) eb += b.energy; else er += b.energy }
    const T = w.totals
    console.log(
      `t=${w.t.toFixed(0).padStart(4)} B=${String(w.counts[0]).padStart(3)} R=${String(w.counts[1]).padStart(3)} F=${String(w.ripe).padStart(3)} eB=${(eb / (w.counts[0] || 1)).toFixed(0)} eR=${(er / (w.counts[1] || 1)).toFixed(0)} +B${T.births[0] - prev.births[0]} +R${T.births[1] - prev.births[1]} boop${T.contacts - prev.contacts} kill${T.fadesByBoop - prev.fadesByBoop} hungB${T.fadesByHunger[0] - prev.fadesByHunger[0]} hungR${T.fadesByHunger[1] - prev.fadesByHunger[1]} ageB${T.fadesByAge[0] - prev.fadesByAge[0]} ageR${T.fadesByAge[1] - prev.fadesByAge[1]} ` +
        Object.entries(acts).sort().map(([k, v]) => `${k}:${v}`).join(' '),
    )
    prev = JSON.parse(JSON.stringify(T))
  }
}
void lastT; void RED

