    headline,
    lines,
    mood,
    lagSec,
    lagCorr,
    blueWaves: bluePeaks.length,
    redWaves: redPeaks.length,
    peakBlue,
    peakRed,
    peakFruit,
    blueGoneAt,
    redGoneAt,
    leveled,
    fruitSupply,
    duration,
  }
}

