      g.font = FONT_BOLD
      g.textAlign = 'left'
      g.textBaseline = 'middle'
      const labels = spreadLabels(
        SERIES.map((s, si) => ({ y: Y(cols[si][n - 1], si), s, v: cols[si][n - 1] })),
        15,
        PAD.t + 4,
        PAD.t + ph,
      )
      for (const l of labels) {
        g.fillStyle = l.s.color
        g.beginPath()
        g.arc(PAD.l + pw + 7, l.y, 3, 0, Math.PI * 2)
        g.fill()
