          role="img"
          aria-label="Line chart of fruit, blue and red counts over time"
        />
        {tip && hoverX !== null && (
          <div className="tip" style={{ left: Math.min(tip.x + 12, 9999), top: tip.y }}>
            <b>{clock(tip.t)}</b>
            {SERIES.map((s, i) => (
              <span key={s.key}>
                <i style={{ background: s.color }} />
                {s.label} <b>{Math.round(tip.v[i])}</b>
              </span>
            ))}
          </div>
        )}
      </div>
