        g.fillText(clock(tt), x, PAD.t + ph + 7)
        g.strokeStyle = INK.axis
        g.beginPath()
        g.moveTo(Math.round(x) + 0.5, PAD.t + ph)
        g.lineTo(Math.round(x) + 0.5, PAD.t + ph + 4)
        g.stroke()
      }

