      g.beginPath()
      g.moveTo(X(t[i0]), Y(0, 0))
      for (let i = i0; i < n; i += stride) g.lineTo(X(t[i]), Y(fruit[i], 0))
      g.lineTo(X(t[n - 1]), Y(fruit[n - 1], 0))
      g.lineTo(X(t[n - 1]), Y(0, 0))
      g.closePath()
      g.fillStyle = 'rgba(0,131,0,0.09)'
      g.fill()
      SERIES.forEach((s, si) => {
        const c = cols[si]
        g.beginPath()
        for (let i = i0; i < n; i += stride) {
          const x = X(t[i])
          const y = Y(c[i], si)
          if (i === i0) g.moveTo(x, y)
          else g.lineTo(x, y)
