        g.moveTo(Math.round(x) + 0.5, PAD.t)
        g.lineTo(Math.round(x) + 0.5, PAD.t + ph)
        g.stroke()
        SERIES.forEach((s, si) => {
          g.fillStyle = INK.surface
          g.strokeStyle = s.color
          g.lineWidth = 2
          g.beginPath()
          g.arc(x, Y(cols[si][i], si), 3.5, 0, Math.PI * 2)
          g.fill()
          g.stroke()
        })
      }
    },
