  const story = useMemo(() => tellStory(world.history, world.params, world.totals), [world, version])
  const pending = PARAM_DEFS.filter((d) => d.onReset && params[d.key] !== applied[d.key])
  const [nb, nr] = world.counts

  return (
    <div className="app">
