              onFollow={setFollow}
              onClose={() => {
                setSelected(null)
                setFollow(false)
              }}
            />
          )}
          <MapKey />
          <div className="transport" role="toolbar" aria-label="Simulation controls">
            <button type="button" className="btn primary play" onClick={togglePlay} aria-label={playing ? 'Pause' : 'Play'}>
