:root {
  --bg: #f3ecdf;
  --panel: #fffdf8;
  --ink: #2b2733;
  --muted: #7a7285;
  --line: #ebe3d4;
  --soft: #f4ede0;
  --blue: #2a78d6;
  --red: #e34948;
  --fruit: #008300;
  --leaf: #3f9a3f;
  --warm: #e8914f;
  --radius: 20px;
  --shadow: 0 1px 0 rgba(255, 255, 255, 0.9) inset, 0 10px 28px -16px rgba(90, 60, 25, 0.28), 0 2px 6px -3px rgba(90, 60, 25, 0.12);
  --head: 'Fredoka Variable', 'Nunito Variable', system-ui, sans-serif;
  --body: 'Nunito Variable', system-ui, sans-serif;
  color-scheme: light;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  background:
    radial-gradient(1200px 600px at 20% -10%, #fbf6ec 0%, transparent 60%),
    radial-gradient(900px 500px at 110% 10%, #f6ead6 0%, transparent 55%),
    var(--bg);
  color: var(--ink);
  font-family: var(--body);
  font-size: 14px;
  line-height: 1.45;
  -webkit-font-smoothing: antialiased;
}

button {
  font: inherit;
  color: inherit;
}

h1,
h3 {
  font-family: var(--head);
  margin: 0;
  letter-spacing: 0.005em;
}

.app {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 360px;
  gap: 18px;
  padding: 18px;
  max-width: 1760px;
  margin: 0 auto;
}

.main {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
}

/* ------------------------------------------------------------ header */

.top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  padding: 2px 4px;
}

.top h1 {
  font-size: 28px;
  font-weight: 650;
  line-height: 1.1;
}

.hud {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px 6px 9px;
  border-radius: 999px;
  background: var(--panel);
  border: 1px solid var(--line);
  box-shadow: var(--shadow);
  font-variant-numeric: tabular-nums;
}

.pill b {
  font-family: var(--head);
  font-size: 17px;
  font-weight: 600;
  min-width: 2ch;
  text-align: right;
}

.pill small {
  color: var(--muted);
  font-weight: 600;
}

.pill.fruit b {
  color: var(--fruit);
}
.pill.blue b {
  color: var(--blue);
}
.pill.red b {
  color: var(--red);
}
.pill.time {
  padding-left: 12px;
}

/* ------------------------------------------------------------ stage */

.stage-wrap {
  position: relative;
  height: clamp(440px, 64vh, 760px);
  border-radius: 30px;
  overflow: hidden;
  border: 1px solid #e6d9c3;
  background: radial-gradient(ellipse 70% 60% at 50% 42%, #fdf8ef 0%, #f1e5d1 62%, #e6d5bb 100%);
  box-shadow: var(--shadow);
}

.stage {
  position: absolute;
  inset: 0;
}

.garden-canvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: grab;
  outline: none;
}

.stage-hint {
  position: absolute;
  top: 14px;
  left: 14px;
  padding: 6px 12px;
  border-radius: 999px;
  background: rgba(255, 253, 248, 0.75);
  backdrop-filter: blur(8px);
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  pointer-events: none;
}

.transport {
  position: absolute;
  left: 50%;
  bottom: 14px;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px;
  border-radius: 999px;
  background: rgba(255, 253, 248, 0.9);
  backdrop-filter: blur(12px);
  border: 1px solid rgba(230, 217, 195, 0.9);
  box-shadow: 0 12px 30px -14px rgba(80, 55, 20, 0.45);
  white-space: nowrap;
}

.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 15px;
  border-radius: 999px;
  border: 1px solid #e3d8c5;
  background: var(--soft);
  font-family: var(--head);
  font-size: 14px;
  font-weight: 550;
  cursor: pointer;
  transition:
    background 0.15s,
    transform 0.08s,
    border-color 0.15s;
}

.btn:hover {
  background: #fff;
  border-color: #d8cab2;
}

.btn:active {
  transform: translateY(1px);
}

.btn:focus-visible,
.seg button:focus-visible,
.preset:focus-visible,
input:focus-visible {
  outline: 2px solid var(--blue);
  outline-offset: 2px;
}

.btn.primary {
  background: var(--ink);
  border-color: var(--ink);
  color: #fff;
  min-width: 100px;
  justify-content: center;
}

.btn.primary:hover {
  background: #403a4a;
}

.btn.small {
  padding: 5px 11px;
  font-size: 13px;
}

.btn.attn {
  border-color: var(--warm);
  background: #fff4e6;
}

.btn .dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--warm);
  box-shadow: 0 0 0 3px rgba(232, 145, 79, 0.25);
}

.speed {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 0 10px 0 8px;
  font-weight: 700;
  color: var(--muted);
  font-size: 12px;
}

.speed b {
  color: var(--ink);
  font-family: var(--head);
  font-size: 14px;
  font-weight: 600;
  min-width: 3.2ch;
  font-variant-numeric: tabular-nums;
}

.speed input {
  width: 110px;
  --c: var(--ink);
}

.pending-bar {
  position: absolute;
  left: 50%;
  bottom: 70px;
  transform: translateX(-50%);
  padding: 7px 14px;
  border-radius: 999px;
  background: #fff4e6;
  border: 1px solid #f3c79d;
  color: #8a4d1c;
  font-weight: 700;
  font-size: 12.5px;
  white-space: nowrap;
  box-shadow: 0 8px 18px -12px rgba(140, 80, 20, 0.5);
}

.pending-bar button {
  border: 0;
  background: none;
  color: #c0621d;
  font-weight: 800;
  text-decoration: underline;
  cursor: pointer;
  padding: 0;
}

.map-key {
  position: absolute;
  left: 14px;
  bottom: 14px;
  max-width: 330px;
  font-size: 12.5px;
}

.map-key summary {
  list-style: none;
  cursor: pointer;
  display: inline-block;
  padding: 7px 13px;
  border-radius: 999px;
  background: rgba(255, 253, 248, 0.88);
  backdrop-filter: blur(8px);
  border: 1px solid rgba(230, 217, 195, 0.9);
  font-weight: 800;
  color: var(--muted);
}

.map-key summary::-webkit-details-marker {
  display: none;
}

.map-key[open] summary {
  color: var(--ink);
}

.map-key ul {
  position: absolute;
  bottom: 40px;
  left: 0;
  width: 330px;
  margin: 0;
  padding: 12px 14px;
  list-style: none;
  display: grid;
  gap: 7px;
  border-radius: 16px;
  background: rgba(255, 253, 248, 0.96);
  border: 1px solid var(--line);
  box-shadow: var(--shadow);
}

.map-key li {
  display: grid;
  grid-template-columns: 18px 1fr;
  gap: 6px;
  align-items: baseline;
}

.map-key li b {
  text-align: center;
  font-family: var(--head);
  font-size: 14px;
}

.k-fruit {
  color: #7fbf2a;
}
.k-red {
  color: var(--red);
}
.k-blue {
  color: #58a8ee;
}
.k-gold {
  color: #e2a400;
}
.k-pink {
  color: #ef6c9c;
}
.k-muted {
  color: #7a8cb8;
}

/* ------------------------------------------------------------ inspector */

.inspector {
  position: absolute;
  top: 14px;
  right: 14px;
  width: 292px;
  padding: 14px 15px 12px;
  border-radius: 20px;
  background: rgba(255, 253, 248, 0.94);
  backdrop-filter: blur(12px);
  border: 1px solid var(--line);
  box-shadow: 0 16px 40px -18px rgba(70, 45, 15, 0.45);
  display: grid;
  gap: 10px;
  font-size: 13px;
}

.inspector.is-blue {
  border-top: 4px solid var(--blue);
}
.inspector.is-red {
  border-top: 4px solid var(--red);
}

.insp-head {
  display: flex;
  align-items: center;
  gap: 10px;
}

.insp-title {
  display: grid;
  gap: 2px;
  flex: 1;
}

.insp-title b {
  font-family: var(--head);
  font-size: 18px;
  font-weight: 600;
  line-height: 1.1;
}

.chip {
  justify-self: start;
  padding: 1px 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
}

.chip-blue {
  background: #e3eefc;
  color: var(--blue);
}
.chip-red {
  background: #fde6e5;
  color: #c7302f;
}

.icon-btn {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: var(--soft);
  cursor: pointer;
  font-size: 17px;
  line-height: 1;
  color: var(--muted);
}

.insp-action {
  margin: 0;
  font-family: var(--head);
  font-size: 15px;
  font-weight: 550;
  padding: 6px 10px;
  border-radius: 12px;
  background: var(--soft);
}

.insp-action.faded {
  color: var(--muted);
}

.meter-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 4px 8px;
  font-weight: 700;
}

.meter-row .num {
  font-variant-numeric: tabular-nums;
}

.meter-row small {
  grid-column: 1 / -1;
  font-weight: 600;
}

.meter {
  grid-column: 1 / -1;
  position: relative;
  height: 10px;
  border-radius: 999px;
  background: #eee6d8;
  overflow: visible;
}

.meter.thin {
  height: 6px;
}

.meter i {
  position: absolute;
  inset: 0 auto 0 0;
  border-radius: 999px;
  background: linear-gradient(90deg, #ffd36b, #ffb020);
  transition: width 0.15s linear;
}

.is-blue .meter.energy i {
  background: linear-gradient(90deg, #8fbcf2, var(--blue));
}
.is-red .meter.energy i {
  background: linear-gradient(90deg, #f3a19d, var(--red));
}

.meter em {
  position: absolute;
  top: -3px;
  bottom: -3px;
  width: 2px;
  margin-left: -1px;
  background: var(--ink);
  border-radius: 2px;
}

.insp-grid {
  margin: 0;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 4px 12px;
}

.insp-grid dt {
  color: var(--muted);
  font-weight: 700;
}

.insp-grid dd {
  margin: 0;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.insp-grid small,
.muted {
  color: var(--muted);
  font-weight: 600;
}

.toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  cursor: pointer;
}

.toggle input {
  accent-color: var(--ink);
  width: 16px;
  height: 16px;
}

/* ------------------------------------------------------------ cards */

.card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 14px 16px 16px;
  min-width: 0;
}

.card-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 10px;
}

.card-head h3 {
  font-size: 16px;
  font-weight: 600;
}

.sub {
  margin: 2px 0 0;
  color: var(--muted);
  font-size: 12.5px;
  font-weight: 600;
}

.charts {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) minmax(300px, 0.9fr);
  gap: 16px;
  align-items: start;
}

.timeline {
  grid-column: 1 / 3;
}

.summary {
  grid-column: 3;
  grid-row: 1 / 3;
}

.chart-box {
  position: relative;
}

.chart {
  display: block;
  width: 100%;
  height: 100%;
}

.seg-group {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.seg {
  display: inline-flex;
  padding: 3px;
  border-radius: 999px;
  background: #f1eadc;
}

.seg button {
  border: 0;
  background: transparent;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 800;
  color: var(--muted);
  cursor: pointer;
}

.seg button.on {
  background: #fff;
  color: var(--ink);
  box-shadow: 0 1px 3px rgba(60, 40, 10, 0.15);
}

.tip {
  position: absolute;
  pointer-events: none;
  display: grid;
  gap: 2px;
  padding: 8px 10px;
  border-radius: 10px;
  background: rgba(43, 39, 51, 0.94);
  color: #fff;
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.tip span {
  display: flex;
  align-items: center;
  gap: 6px;
}

.tip i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  margin: -2px 0 8px;
  font-size: 12px;
  font-weight: 700;
  color: var(--muted);
}

.legend span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.legend b {
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

/* ------------------------------------------------------------ summary */

.mood {
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 800;
  white-space: nowrap;
}

.mood.good {
  background: #e5f4df;
  color: #2f7d2c;
}
.mood.calm {
  background: #eef0e2;
  color: #6a6b2e;
}
.mood.warn {
  background: #fff1dd;
  color: #a4580f;
}
.mood.bad {
  background: #fde6e5;
  color: #b3302c;
}
.mood.neutral {
  background: var(--soft);
  color: var(--muted);
}

.headline {
  margin: 0 0 8px;
  font-family: var(--head);
  font-size: 19px;
  font-weight: 550;
  line-height: 1.25;
}

.story {
  margin: 0 0 14px;
  padding-left: 18px;
  display: grid;
  gap: 5px;
  font-weight: 600;
  color: #4a4453;
}

.story li::marker {
  color: #c9b99f;
}

.stats {
  margin: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px 12px;
  padding-top: 12px;
  border-top: 1px dashed var(--line);
}

.stats dt {
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.stats dd {
  margin: 1px 0 0;
  font-family: var(--head);
  font-size: 16px;
  font-weight: 550;
  font-variant-numeric: tabular-nums;
}

.stats small {
  font-family: var(--body);
  font-size: 12px;
  color: var(--muted);
  font-weight: 700;
}

.c-blue {
  color: var(--blue);
}
.c-red {
  color: var(--red);
}
.c-fruit {
  color: var(--fruit);
}

/* ------------------------------------------------------------ sidebar */

.side {
  position: sticky;
  top: 18px;
  align-self: start;
  max-height: calc(100vh - 36px);
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: #dccfb8 transparent;
  padding-right: 2px;
}

.controls {
  display: grid;
  gap: 14px;
}

.preset-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.preset {
  position: relative;
  display: grid;
  gap: 2px;
  text-align: left;
  padding: 9px 11px 10px 14px;
  border-radius: 14px;
  border: 1px solid var(--line);
  background: #fbf7ef;
  cursor: pointer;
  overflow: hidden;
  transition:
    border-color 0.15s,
    background 0.15s;
}

.preset::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  background: var(--pc, var(--leaf));
}

.preset:hover {
  background: #fff;
  border-color: #dccfb8;
}

.preset.on {
  background: #fff;
  border-color: var(--ink);
  box-shadow: 0 0 0 1px var(--ink) inset;
}

.preset b {
  font-family: var(--head);
  font-size: 14px;
  font-weight: 600;
  display: flex;
  gap: 6px;
  align-items: center;
}

.preset em {
  font-style: normal;
  font-family: var(--body);
  font-size: 10.5px;
  font-weight: 800;
  padding: 0 6px;
  border-radius: 999px;
  background: #fff1dd;
  color: #a4580f;
}

.preset span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
  line-height: 1.3;
}

.preset:last-child:nth-child(odd) {
  grid-column: 1 / -1;
}

.p-balanced {
  --pc: #3f9a3f;
}
.p-rich {
  --pc: #8fd13a;
}
.p-redheavy {
  --pc: var(--red);
}
.p-fragile {
  --pc: #9b7fd6;
}
.p-lowfruit {
  --pc: #d9a441;
}

.group {
  --accent: var(--leaf);
  display: grid;
  gap: 12px;
}

.group .card-head {
  margin-bottom: 0;
  padding-left: 10px;
  border-left: 4px solid var(--accent);
}

.g-garden {
  --accent: #3f9a3f;
}
.g-blue {
  --accent: var(--blue);
}
.g-red {
  --accent: var(--red);
}
.g-world {
  --accent: #a0825e;
}

.ctl {
  display: grid;
  grid-template-columns: 1fr auto auto;
  align-items: center;
  gap: 1px 8px;
}

.ctl label {
  font-weight: 800;
  font-size: 13px;
}

.ctl output {
  font-family: var(--head);
  font-weight: 550;
  font-size: 13.5px;
  font-variant-numeric: tabular-nums;
  color: var(--ink);
  grid-column: 3;
}

.ctl input[type='range'],
.ctl .seed-row,
.ctl .hint {
  grid-column: 1 / -1;
}

.ctl .hint {
  color: var(--muted);
  font-size: 11.5px;
  font-weight: 600;
  line-height: 1.3;
}

.pending {
  grid-column: 2;
  font-size: 10.5px;
  font-weight: 800;
  padding: 1px 7px;
  border-radius: 999px;
  background: #fff1dd;
  color: #a4580f;
}

.seed-row {
  display: flex;
  gap: 8px;
  margin: 3px 0 1px;
}

.seed-row input {
  flex: 1;
  min-width: 0;
  padding: 6px 10px;
  border-radius: 10px;
  border: 1px solid #e3d8c5;
  background: #fff;
  font: inherit;
  font-weight: 700;
}

/* range */
input[type='range'] {
  --c: var(--accent, var(--ink));
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 22px;
  margin: 2px 0;
  background: transparent;
  cursor: pointer;
}

input[type='range']::-webkit-slider-runnable-track {
  height: 8px;
  border-radius: 999px;
  background: linear-gradient(to right, var(--c) var(--p, 50%), #ebe2d2 var(--p, 50%));
}

input[type='range']::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 20px;
  height: 20px;
  margin-top: -6px;
  border-radius: 50%;
  background: #fff;
  border: 3px solid var(--c);
  box-shadow: 0 2px 6px rgba(60, 40, 10, 0.2);
  transition: transform 0.1s;
}

input[type='range']:active::-webkit-slider-thumb {
  transform: scale(1.12);
}

input[type='range']::-moz-range-track {
  height: 8px;
  border-radius: 999px;
  background: #ebe2d2;
}

input[type='range']::-moz-range-progress {
  height: 8px;
  border-radius: 999px;
  background: var(--c);
}

input[type='range']::-moz-range-thumb {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #fff;
  border: 3px solid var(--c);
  box-shadow: 0 2px 6px rgba(60, 40, 10, 0.2);
}

.speed input[type='range']::-webkit-slider-runnable-track {
  background: #e6dccb;
}

/* ------------------------------------------------------------ responsive */

@media (max-width: 1280px) {
  .charts {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }
  .timeline {
    grid-column: 1 / -1;
  }
  .summary {
    grid-column: 1 / -1;
    grid-row: auto;
  }
}

@media (max-width: 1080px) {
  .app {
    grid-template-columns: minmax(0, 1fr);
  }
  .side {
    position: static;
    max-height: none;
    overflow: visible;
  }
  .controls {
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  }
  .presets {
    grid-column: 1 / -1;
  }
}

@media (max-width: 760px) {
  .app {
    padding: 10px;
  }
  .charts {
    grid-template-columns: minmax(0, 1fr);
  }
  .transport {
    flex-wrap: wrap;
    justify-content: center;
    border-radius: 22px;
    width: calc(100% - 20px);
  }
  .inspector {
    width: auto;
    left: 10px;
    right: 10px;
    top: auto;
    bottom: 130px;
  }
  .map-key,
  .stage-hint {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
  }
}

:root {
  --bg: #f3ecdf;
  --panel: #fffdf8;
  --ink: #2b2733;
  --muted: #7a7285;
  --line: #ebe3d4;
  --soft: #f4ede0;
  --blue: #2a78d6;
  --red: #e34948;
  --fruit: #008300;
  --leaf: #3f9a3f;
  --warm: #e8914f;
  --radius: 20px;
  --shadow: 0 1px 0 rgba(255, 255, 255, 0.9) inset, 0 10px 28px -16px rgba(90, 60, 25, 0.28), 0 2px 6px -3px rgba(90, 60, 25, 0.12);
  --head: 'Fredoka Variable', 'Nunito Variable', system-ui, sans-serif;
  --body: 'Nunito Variable', system-ui, sans-serif;
  color-scheme: light;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  background:
    radial-gradient(1200px 600px at 20% -10%, #fbf6ec 0%, transparent 60%),
    radial-gradient(900px 500px at 110% 10%, #f6ead6 0%, transparent 55%),
    var(--bg);
  color: var(--ink);
  font-family: var(--body);
  font-size: 14px;
  line-height: 1.45;
  -webkit-font-smoothing: antialiased;
}

button {
  font: inherit;
  color: inherit;
}

h1,
h3 {
  font-family: var(--head);
  margin: 0;
  letter-spacing: 0.005em;
}

.app {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 360px;
  gap: 18px;
  padding: 18px;
  max-width: 1760px;
  margin: 0 auto;
}

.main {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
}

/* ------------------------------------------------------------ header */

.top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  padding: 2px 4px;
}

.top h1 {
  font-size: 28px;
  font-weight: 650;
  line-height: 1.1;
}

.hud {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px 6px 9px;
  border-radius: 999px;
  background: var(--panel);
  border: 1px solid var(--line);
  box-shadow: var(--shadow);
  font-variant-numeric: tabular-nums;
}

.pill b {
  font-family: var(--head);
  font-size: 17px;
  font-weight: 600;
  min-width: 2ch;
  text-align: right;
}

.pill small {
  color: var(--muted);
  font-weight: 600;
}

.pill.fruit b {
  color: var(--fruit);
}
.pill.blue b {
  color: var(--blue);
}
.pill.red b {
  color: var(--red);
}
.pill.time {
  padding-left: 12px;
}

/* ------------------------------------------------------------ stage */

.stage-wrap {
  position: relative;
  height: clamp(440px, 64vh, 760px);
  border-radius: 30px;
  overflow: hidden;
  border: 1px solid #e6d9c3;
  background: radial-gradient(ellipse 70% 60% at 50% 42%, #fdf8ef 0%, #f1e5d1 62%, #e6d5bb 100%);
  box-shadow: var(--shadow);
}

.stage {
  position: absolute;
  inset: 0;
}

.garden-canvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: grab;
  outline: none;
}

.stage-hint {
  position: absolute;
  top: 14px;
  left: 14px;
  padding: 6px 12px;
  border-radius: 999px;
  background: rgba(255, 253, 248, 0.75);
  backdrop-filter: blur(8px);
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  pointer-events: none;
}

.transport {
  position: absolute;
  left: 50%;
  bottom: 14px;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px;
  border-radius: 999px;
  background: rgba(255, 253, 248, 0.9);
  backdrop-filter: blur(12px);
  border: 1px solid rgba(230, 217, 195, 0.9);
  box-shadow: 0 12px 30px -14px rgba(80, 55, 20, 0.45);
  white-space: nowrap;
}

.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 15px;
  border-radius: 999px;
  border: 1px solid #e3d8c5;
  background: var(--soft);
  font-family: var(--head);
  font-size: 14px;
  font-weight: 550;
  cursor: pointer;
  transition:
    background 0.15s,
    transform 0.08s,
    border-color 0.15s;
}

.btn:hover {
  background: #fff;
  border-color: #d8cab2;
}

.btn:active {
  transform: translateY(1px);
}

.btn:focus-visible,
.seg button:focus-visible,
.preset:focus-visible,
input:focus-visible {
  outline: 2px solid var(--blue);
  outline-offset: 2px;
}

.btn.primary {
  background: var(--ink);
  border-color: var(--ink);
  color: #fff;
  min-width: 100px;
  justify-content: center;
}

.btn.primary:hover {
  background: #403a4a;
}

.btn.small {
  padding: 5px 11px;
  font-size: 13px;
}

.btn.attn {
  border-color: var(--warm);
  background: #fff4e6;
}

.btn .dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--warm);
  box-shadow: 0 0 0 3px rgba(232, 145, 79, 0.25);
}

.speed {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 0 10px 0 8px;
  font-weight: 700;
  color: var(--muted);
  font-size: 12px;
}

.speed b {
  color: var(--ink);
  font-family: var(--head);
  font-size: 14px;
  font-weight: 600;
  min-width: 3.2ch;
  font-variant-numeric: tabular-nums;
}

.speed input {
  width: 110px;
  --c: var(--ink);
}

.pending-bar {
  position: absolute;
  left: 50%;
  bottom: 70px;
  transform: translateX(-50%);
  padding: 7px 14px;
  border-radius: 999px;
  background: #fff4e6;
  border: 1px solid #f3c79d;
  color: #8a4d1c;
  font-weight: 700;
  font-size: 12.5px;
  white-space: nowrap;
  box-shadow: 0 8px 18px -12px rgba(140, 80, 20, 0.5);
}

.pending-bar button {
  border: 0;
  background: none;
  color: #c0621d;
  font-weight: 800;
  text-decoration: underline;
  cursor: pointer;
  padding: 0;
}

.map-key {
  position: absolute;
  left: 14px;
  bottom: 14px;
  max-width: 330px;
  font-size: 12.5px;
}

.map-key summary {
  list-style: none;
  cursor: pointer;
  display: inline-block;
  padding: 7px 13px;
  border-radius: 999px;
  background: rgba(255, 253, 248, 0.88);
  backdrop-filter: blur(8px);
  border: 1px solid rgba(230, 217, 195, 0.9);
  font-weight: 800;
  color: var(--muted);
}

.map-key summary::-webkit-details-marker {
  display: none;
}

.map-key[open] summary {
  color: var(--ink);
}

.map-key ul {
  position: absolute;
  bottom: 40px;
  left: 0;
  width: 330px;
  margin: 0;
  padding: 12px 14px;
  list-style: none;
  display: grid;
  gap: 7px;
  border-radius: 16px;
  background: rgba(255, 253, 248, 0.96);
  border: 1px solid var(--line);
  box-shadow: var(--shadow);
}

.map-key li {
  display: grid;
  grid-template-columns: 18px 1fr;
  gap: 6px;
  align-items: baseline;
}

.map-key li b {
  text-align: center;
  font-family: var(--head);
  font-size: 14px;
}

.k-fruit {
  color: #7fbf2a;
}
.k-red {
  color: var(--red);
}
.k-blue {
  color: #58a8ee;
}
.k-gold {
  color: #e2a400;
}
.k-pink {
  color: #ef6c9c;
}
.k-muted {
  color: #7a8cb8;
}

/* ------------------------------------------------------------ inspector */

.inspector {
  position: absolute;
  top: 14px;
  right: 14px;
  width: 292px;
  padding: 14px 15px 12px;
  border-radius: 20px;
  background: rgba(255, 253, 248, 0.94);
  backdrop-filter: blur(12px);
  border: 1px solid var(--line);
  box-shadow: 0 16px 40px -18px rgba(70, 45, 15, 0.45);
  display: grid;
  gap: 10px;
  font-size: 13px;
}

.inspector.is-blue {
  border-top: 4px solid var(--blue);
}
.inspector.is-red {
  border-top: 4px solid var(--red);
}

.insp-head {
  display: flex;
  align-items: center;
  gap: 10px;
}

.insp-title {
  display: grid;
  gap: 2px;
  flex: 1;
}

.insp-title b {
  font-family: var(--head);
  font-size: 18px;
  font-weight: 600;
  line-height: 1.1;
}

.chip {
  justify-self: start;
  padding: 1px 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
}

.chip-blue {
  background: #e3eefc;
  color: var(--blue);
}
.chip-red {
  background: #fde6e5;
  color: #c7302f;
}

.icon-btn {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: var(--soft);
  cursor: pointer;
  font-size: 17px;
  line-height: 1;
  color: var(--muted);
}

.insp-action {
  margin: 0;
  font-family: var(--head);
  font-size: 15px;
  font-weight: 550;
  padding: 6px 10px;
  border-radius: 12px;
  background: var(--soft);
}

.insp-action.faded {
  color: var(--muted);
}

.meter-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 4px 8px;
  font-weight: 700;
}

.meter-row .num {
  font-variant-numeric: tabular-nums;
}

.meter-row small {
  grid-column: 1 / -1;
  font-weight: 600;
}

.meter {
  grid-column: 1 / -1;
  position: relative;
  height: 10px;
  border-radius: 999px;
  background: #eee6d8;
  overflow: visible;
}

.meter.thin {
  height: 6px;
}

.meter i {
  position: absolute;
  inset: 0 auto 0 0;
  border-radius: 999px;
  background: linear-gradient(90deg, #ffd36b, #ffb020);
  transition: width 0.15s linear;
}

.is-blue .meter.energy i {
  background: linear-gradient(90deg, #8fbcf2, var(--blue));
}
.is-red .meter.energy i {
  background: linear-gradient(90deg, #f3a19d, var(--red));
}

.meter em {
  position: absolute;
  top: -3px;
  bottom: -3px;
  width: 2px;
  margin-left: -1px;
  background: var(--ink);
  border-radius: 2px;
}

.insp-grid {
  margin: 0;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 4px 12px;
}

.insp-grid dt {
  color: var(--muted);
  font-weight: 700;
}

.insp-grid dd {
  margin: 0;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.insp-grid small,
.muted {
  color: var(--muted);
  font-weight: 600;
}

.toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 700;
  cursor: pointer;
}

.toggle input {
  accent-color: var(--ink);
  width: 16px;
  height: 16px;
}

/* ------------------------------------------------------------ cards */

.card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 14px 16px 16px;
  min-width: 0;
}

.card-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 10px;
}

.card-head h3 {
  font-size: 16px;
  font-weight: 600;
}

.sub {
  margin: 2px 0 0;
  color: var(--muted);
  font-size: 12.5px;
  font-weight: 600;
}

.charts {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) minmax(300px, 0.9fr);
  gap: 16px;
  align-items: start;
}

.timeline {
  grid-column: 1 / 3;
}

.summary {
  grid-column: 3;
  grid-row: 1 / 3;
}

.chart-box {
  position: relative;
}

.chart {
  display: block;
  width: 100%;
  height: 100%;
}

.seg-group {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.seg {
  display: inline-flex;
  padding: 3px;
  border-radius: 999px;
  background: #f1eadc;
}

.seg button {
  border: 0;
  background: transparent;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 800;
  color: var(--muted);
  cursor: pointer;
}

.seg button.on {
  background: #fff;
  color: var(--ink);
  box-shadow: 0 1px 3px rgba(60, 40, 10, 0.15);
}

.tip {
  position: absolute;
  pointer-events: none;
  display: grid;
  gap: 2px;
  padding: 8px 10px;
  border-radius: 10px;
  background: rgba(43, 39, 51, 0.94);
  color: #fff;
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.tip span {
  display: flex;
  align-items: center;
  gap: 6px;
}

.tip i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  margin: -2px 0 8px;
  font-size: 12px;
  font-weight: 700;
  color: var(--muted);
}

.legend span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.legend b {
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

/* ------------------------------------------------------------ summary */

.mood {
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 800;
  white-space: nowrap;
}

.mood.good {
  background: #e5f4df;
  color: #2f7d2c;
}
.mood.calm {
  background: #eef0e2;
  color: #6a6b2e;
}
.mood.warn {
  background: #fff1dd;
  color: #a4580f;
}
.mood.bad {
  background: #fde6e5;
  color: #b3302c;
}
.mood.neutral {
  background: var(--soft);
  color: var(--muted);
}

.headline {
  margin: 0 0 8px;
  font-family: var(--head);
  font-size: 19px;
  font-weight: 550;
  line-height: 1.25;
}

.story {
  margin: 0 0 14px;
  padding-left: 18px;
  display: grid;
  gap: 5px;
  font-weight: 600;
  color: #4a4453;
}

.story li::marker {
  color: #c9b99f;
}

.stats {
  margin: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px 12px;
  padding-top: 12px;
  border-top: 1px dashed var(--line);
}

.stats dt {
  color: var(--muted);
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.stats dd {
  margin: 1px 0 0;
  font-family: var(--head);
  font-size: 16px;
  font-weight: 550;
  font-variant-numeric: tabular-nums;
}

.stats small {
  font-family: var(--body);
  font-size: 12px;
  color: var(--muted);
  font-weight: 700;
}

.c-blue {
  color: var(--blue);
}
.c-red {
  color: var(--red);
}
.c-fruit {
  color: var(--fruit);
}

/* ------------------------------------------------------------ sidebar */

.side {
  position: sticky;
  top: 18px;
  align-self: start;
  max-height: calc(100vh - 36px);
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: #dccfb8 transparent;
  padding-right: 2px;
}

.controls {
  display: grid;
  gap: 14px;
}

.preset-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.preset {
  position: relative;
  display: grid;
  gap: 2px;
  text-align: left;
  padding: 9px 11px 10px 14px;
  border-radius: 14px;
  border: 1px solid var(--line);
  background: #fbf7ef;
  cursor: pointer;
  overflow: hidden;
  transition:
    border-color 0.15s,
    background 0.15s;
}

.preset::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  background: var(--pc, var(--leaf));
}

.preset:hover {
  background: #fff;
  border-color: #dccfb8;
}

.preset.on {
  background: #fff;
  border-color: var(--ink);
  box-shadow: 0 0 0 1px var(--ink) inset;
}

.preset b {
  font-family: var(--head);
  font-size: 14px;
  font-weight: 600;
  display: flex;
  gap: 6px;
  align-items: center;
}

.preset em {
  font-style: normal;
  font-family: var(--body);
  font-size: 10.5px;
  font-weight: 800;
  padding: 0 6px;
  border-radius: 999px;
  background: #fff1dd;
  color: #a4580f;
}

.preset span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
  line-height: 1.3;
}

.preset:last-child:nth-child(odd) {
  grid-column: 1 / -1;
}

.p-balanced {
  --pc: #3f9a3f;
}
.p-rich {
  --pc: #8fd13a;
}
.p-redheavy {
  --pc: var(--red);
}
.p-fragile {
  --pc: #9b7fd6;
}
.p-lowfruit {
  --pc: #d9a441;
}

.group {
  --accent: var(--leaf);
  display: grid;
  gap: 12px;
}

.group .card-head {
  margin-bottom: 0;
  padding-left: 10px;
  border-left: 4px solid var(--accent);
}

.g-garden {
  --accent: #3f9a3f;
}
.g-blue {
  --accent: var(--blue);
}
.g-red {
  --accent: var(--red);
}
.g-world {
  --accent: #a0825e;
}

.ctl {
  display: grid;
  grid-template-columns: 1fr auto auto;
  align-items: center;
  gap: 1px 8px;
}

.ctl label {
  font-weight: 800;
  font-size: 13px;
}

.ctl output {
  font-family: var(--head);
  font-weight: 550;
  font-size: 13.5px;
  font-variant-numeric: tabular-nums;
  color: var(--ink);
  grid-column: 3;
}

.ctl input[type='range'],
.ctl .seed-row,
.ctl .hint {
  grid-column: 1 / -1;
}

.ctl .hint {
  color: var(--muted);
  font-size: 11.5px;
  font-weight: 600;
  line-height: 1.3;
}

.pending {
  grid-column: 2;
  font-size: 10.5px;
  font-weight: 800;
  padding: 1px 7px;
  border-radius: 999px;
  background: #fff1dd;
  color: #a4580f;
}

.seed-row {
  display: flex;
  gap: 8px;
  margin: 3px 0 1px;
}

.seed-row input {
  flex: 1;
  min-width: 0;
  padding: 6px 10px;
  border-radius: 10px;
  border: 1px solid #e3d8c5;
  background: #fff;
  font: inherit;
  font-weight: 700;
}

/* range */
input[type='range'] {
  --c: var(--accent, var(--ink));
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 22px;
  margin: 2px 0;
  background: transparent;
  cursor: pointer;
}

input[type='range']::-webkit-slider-runnable-track {
  height: 8px;
  border-radius: 999px;
  background: linear-gradient(to right, var(--c) var(--p, 50%), #ebe2d2 var(--p, 50%));
}

input[type='range']::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 20px;
  height: 20px;
  margin-top: -6px;
  border-radius: 50%;
  background: #fff;
  border: 3px solid var(--c);
  box-shadow: 0 2px 6px rgba(60, 40, 10, 0.2);
  transition: transform 0.1s;
}

input[type='range']:active::-webkit-slider-thumb {
  transform: scale(1.12);
}

input[type='range']::-moz-range-track {
  height: 8px;
  border-radius: 999px;
  background: #ebe2d2;
}

input[type='range']::-moz-range-progress {
  height: 8px;
  border-radius: 999px;
  background: var(--c);
}

input[type='range']::-moz-range-thumb {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #fff;
  border: 3px solid var(--c);
  box-shadow: 0 2px 6px rgba(60, 40, 10, 0.2);
}

.speed input[type='range']::-webkit-slider-runnable-track {
  background: #e6dccb;
}

/* ------------------------------------------------------------ responsive */

@media (max-width: 1280px) {
  .charts {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }
  .timeline {
    grid-column: 1 / -1;
  }
  .summary {
    grid-column: 1 / -1;
    grid-row: auto;
  }
}

@media (max-width: 1080px) {
  .app {
    grid-template-columns: minmax(0, 1fr);
  }
  .side {
    position: static;
    max-height: none;
    overflow: visible;
  }
  .controls {
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  }
  .presets {
    grid-column: 1 / -1;
  }
}

@media (max-width: 760px) {
  .app {
    padding: 10px;
  }
  .charts {
    grid-template-columns: minmax(0, 1fr);
  }
  .transport {
    flex-wrap: wrap;
    justify-content: center;
    border-radius: 22px;
    width: calc(100% - 20px);
  }
  .inspector {
    width: auto;
    left: 10px;
    right: 10px;
    top: auto;
    bottom: 130px;
  }
  .map-key,
  .stage-hint {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
  }
}

